                dialog.setContentPane(new HistoryBrowserPanel(records, id -> {
                    dialog.dispose();
                    reveal.accept(active, id);
                }));
                dialog.pack();
                DialogPlacement.center(dialog, support.getOwner());
                dialog.setVisible(true);
            });
        });
    }
