            }
        });
        JButton open = new JButton("Show selected");
        open.setEnabled(false);
        open.setToolTipText("Close history and reveal the selected milestone in the sidebar.");
        table.getSelectionModel().addListSelectionListener(event -> open.setEnabled(table.getSelectedRow() >= 0 && !shown.get(table.convertRowIndexToModel(table.getSelectedRow())).goalId.isEmpty()));
        open.addActionListener(event -> {
            if (table.getSelectedRow() >= 0) {
                reveal.accept(shown.get(table.convertRowIndexToModel(table.getSelectedRow())).goalId);
            }
        });
        JPanel bottom = new JPanel(new BorderLayout(8, 8));
        bottom.add(summary, BorderLayout.CENTER);
        bottom.add(open, BorderLayout.EAST);
        JLabel note = new JLabel("UTC · incomplete = last observed, not a confirmed miss · unobserved gaps may span several periods · dates are first observations");
        note.setFont(FontManager.getRunescapeSmallFont());
        bottom.add(note, BorderLayout.SOUTH);
        add(filters, BorderLayout.NORTH);
        add(new JScrollPane(table), BorderLayout.CENTER);
        add(bottom, BorderLayout.SOUTH);
        DocumentListener listener = new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent event) {
                filter();
            }
            @Override
            public void removeUpdate(DocumentEvent event) {
                filter();
            }
            @Override
            public void changedUpdate(DocumentEvent event) {
                filter();
            }
        };
        search.getDocument().addDocumentListener(listener);
        from.addPropertyChangeListener("date", event -> filter());
        to.addPropertyChangeListener("date", event -> filter());
        schedule.addActionListener(event -> filter());
        setPreferredSize(new Dimension(900, 460));
        filter();
    }
    private static String date(long value) {
        return value <= 0 ? "—" : DATE.format(Instant.ofEpochMilli(value));
    }
    private void filter() {
        long first;
        long last;
        try {
            first = from.getDate() == null ? 0 : from.getDate().atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();
            last = to.getDate() == null ? Long.MAX_VALUE : to.getDate().plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();
            if (last <= first) {
                throw new IllegalArgumentException();
            }
        } catch (RuntimeException exception) {
            summary.setText("Choose an end date on or after the start date.");
            return;
        }
        RepeatSchedule repeat = schedule.getSelectedIndex() == 0 ? null : RepeatSchedule.values()[schedule.getSelectedIndex() - 1];
        table.clearSelection();
        shown.clear();
        model.setRowCount(0);
        long complete = 0;
        long incomplete = 0;
        long unobserved = 0;
        long milestones = 0;
        for (HistoryRecord record : records) {
            if (!record.matches(search.getText(), repeat, first, last)) {
                continue;
            }
            shown.add(record);
            model.addRow(new Object[]{record.title, record.lifetime ? "Lifetime" : record.schedule.toString(), date(record.start), date(record.end), record.progress, record.target, record.outcome, date(record.baseline), date(record.observed), date(record.completed)});
            if (record.lifetime) {
                milestones++;
            } else if (record.completed > 0) {
                complete++;
            } else if (record.progress == null) {
                unobserved++;
            } else if (record.outcome.startsWith("Incomplete")) {
                incomplete++;
            }
        }
        summary.setText("<html>" + shown.size() + " records · " + complete + " completed periods · " + incomplete + " incomplete<br>" + unobserved + " unobserved / waiting · " + milestones + " lifetime milestones</html>");
    }
}

package com.grindstone.ui.components;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.RenderingHints;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import lombok.Getter;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/18/2026
 */
public class ItemComponent extends JPanel {
    public static final int CELL_SIZE = 40;
    private static final int IMAGE_WIDTH = 36;
    private static final int IMAGE_HEIGHT = 32;
    private static final Color DEFAULT_BORDER_COLOR = ColorScheme.BORDER_COLOR;
    private static final Font AMOUNT_FONT = FontManager.getRunescapeSmallFont();

    private final ItemManager itemManager;
    @Getter
    private ItemComposition item;
    @Getter
    private int amount = 1;
    @Getter
    private Color borderColor = DEFAULT_BORDER_COLOR;
    private int renderedItemId = -1;
    private int itemId = -1;
    private String itemName = "";
    private String amountText = "";
    @Getter
    private BufferedImage image;
    private Boolean obtained;
    private boolean hovered;

    public ItemComponent(ItemManager itemManager, ItemComposition item) {
        this(itemManager, item, null, 1, item == null ? null : item.getName(), null);
    }

    public ItemComponent(ItemManager itemManager, ItemComposition item, BufferedImage image, int amount, String tooltip, Color borderColor) {
        this.itemManager = itemManager;
        setOpaque(false);
        setPreferredSize(new Dimension(CELL_SIZE, CELL_SIZE));
        setMinimumSize(new Dimension(CELL_SIZE, CELL_SIZE));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, CELL_SIZE));
        setItem(item);
        if (image != null) {
            setImage(image);
        }
        setAmount(amount);
        setBorderColor(borderColor);
        setTooltip(tooltip);
        addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent event) {
                hovered = true;
                repaint();
            }

            @Override
            public void mouseExited(MouseEvent event) {
                hovered = false;
                repaint();
            }
        });
    }

    public int getItemId() {
        return itemId;
    }

    public String getItemName() {
        return itemName;
    }

    public ItemComponent(int itemId, String itemName, BufferedImage image, String tooltip, boolean obtained) {
        this(null, null, image, 1, tooltip, null);
        this.itemId = itemId;
        this.itemName = itemName;
        getAccessibleContext().setAccessibleName(itemName);
        setObtained(obtained);
    }


    public void setItem(ItemComposition item) {
        this.item = item;
        itemId = item == null ? -1 : item.getId();
        itemName = item == null ? "" : item.getName();
        int nextId = getItemId();
        if (renderedItemId != nextId) {
            renderedItemId = nextId;
            setImage(itemManager == null || nextId <= 0 ? null : itemManager.getImage(nextId));
        }
        getAccessibleContext().setAccessibleName(getItemName());
        repaint();
    }

    public void setImage(BufferedImage image) {
        if (this.image == image) {
            return;
        }
        this.image = image;
        if (image instanceof AsyncBufferedImage) {
            ((AsyncBufferedImage) image).onLoaded(() -> SwingUtilities.invokeLater(this::repaint));
        }
        repaint();
    }

    public void setObtained(boolean obtained) {
        if (this.obtained != null && this.obtained == obtained) {
            return;
        }
        this.obtained = obtained;
        getAccessibleContext().setAccessibleDescription(obtained ? "Obtained collection-log item" : "Missing collection-log item");
        repaint();
    }

    public void setAmount(int amount) {
        int next = Math.max(1, amount);
        if (this.amount == next) {
            return;
        }
        this.amount = next;
        amountText = formatAmount(next);
        repaint();
    }

    public void setTooltip(String tooltip) {
        setToolTipText(tooltip);
    }

    public void setBorderColor(Color borderColor) {
        Color next = borderColor == null ? DEFAULT_BORDER_COLOR : borderColor;
        if (next.equals(this.borderColor)) {
            return;
        }
        this.borderColor = next;
        repaint();
    }

    @Override
    protected void paintComponent(Graphics graphics) {
        super.paintComponent(graphics);
        Graphics2D g = (Graphics2D) graphics.create();
        try {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setColor(hovered ? ColorScheme.DARKER_GRAY_HOVER_COLOR : Boolean.TRUE.equals(obtained) ? new Color(36, 47, 39) : ColorScheme.DARKER_GRAY_COLOR);
            g.fillRoundRect(0, 0, getWidth(), getHeight(), 6, 6);
            g.setColor(hovered ? ColorScheme.LIGHT_GRAY_COLOR : Boolean.TRUE.equals(obtained) ? new Color(65, 87, 69) : borderColor);
            g.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 6, 6);
            if (image != null) {
                if (Boolean.FALSE.equals(obtained) && !hovered) {
                    g.setComposite(AlphaComposite.SrcOver.derive(0.55f));
                }
                int width = Math.min(IMAGE_WIDTH, image.getWidth());
                int height = Math.min(IMAGE_HEIGHT, image.getHeight());
                g.drawImage(image, (getWidth() - width) / 2, (getHeight() - height) / 2, null);
                g.setComposite(AlphaComposite.SrcOver);
            }
            if (Boolean.TRUE.equals(obtained)) {
                int x = getWidth() - 14;
                int y = getHeight() - 14;
                g.setColor(new Color(28, 41, 31));
                g.fillOval(x, y, 12, 12);
                g.setColor(new Color(134, 190, 139));
                g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                g.drawLine(x + 3, y + 6, x + 5, y + 8);
                g.drawLine(x + 5, y + 8, x + 9, y + 4);
            }
            if (amount > 1) {
                g.setFont(AMOUNT_FONT);
                g.setColor(Color.BLACK);
                g.drawString(amountText, 4, 13);
                g.setColor(Color.YELLOW);
                g.drawString(amountText, 3, 12);
            }
        } finally {
            g.dispose();
        }
    }

    private static String formatAmount(int amount) {
        if (amount >= 1_000_000) {
            return (amount / 1_000_000) + "M";
        }
        if (amount >= 100_000) {
            return (amount / 1_000) + "K";
        }
        return Integer.toString(amount);
    }
}

package com.grindstone.ui.components;

import com.grindstone.ui.util.UiTypography;
import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.HashSet;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/18/2026
 */
public class ItemContainerComponent extends JPanel {
    private static final int GAP = 4;
    private final JPanel grid = new JPanel();
    private final JButton showMore = new JButton();
    private final JLabel emptyLabel = new JLabel("No items to display");
    private final List<ItemComponent> items = new ArrayList<>();
    private List<ItemComponent> visibleItems = Collections.emptyList();
    private int itemsPerRow = 4;
    private int maxRows = 5;
    private int columns = 4;
    private boolean expanded;

    public ItemContainerComponent() {
        super(new BorderLayout(0, 6));
        setOpaque(false);
        setAlignmentX(LEFT_ALIGNMENT);
        grid.setOpaque(false);
        grid.setLayout(new GridLayout(0, columns, GAP, GAP));
        emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        emptyLabel.setFont(UiTypography.BODY);
        emptyLabel.setBorder(BorderFactory.createEmptyBorder(6, 0, 6, 0));
        showMore.setFont(UiTypography.BODY);
        showMore.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        showMore.addActionListener(event -> {
            expanded = !expanded;
            refresh();
        });
        add(grid, BorderLayout.CENTER);
        add(showMore, BorderLayout.SOUTH);
        refresh();
    }

    public void configure(int itemsPerRow, int maxRows) {
        int nextColumns = Math.max(1, Math.min(4, itemsPerRow));
        int nextRows = Math.max(1, Math.min(10, maxRows));
        if (this.itemsPerRow == nextColumns && this.maxRows == nextRows) {
            return;
        }
        this.itemsPerRow = nextColumns;
        this.maxRows = nextRows;
        refresh();
    }

    public void set(List<ItemComponent> components) {
        List<ItemComponent> next = new ArrayList<>();
        if (components != null) {
            Set<ItemComponent> seen = new HashSet<>();
            for (ItemComponent component : components) {
                if (component != null && seen.add(component)) {
                    next.add(component);
                }
            }
        }
        if (items.equals(next)) {
            return;
        }
        items.clear();
        items.addAll(next);
        refresh();
    }

    public void add(ItemComponent component) {
        if (component == null || items.contains(component)) {
            return;
        }
        items.add(component);
        refresh();
    }

    public void clear() {
        if (items.isEmpty()) {
            return;
        }
        items.clear();
        expanded = false;
        refresh();
    }

    public List<ItemComponent> getItems() {
        return Collections.unmodifiableList(items);
    }

    public void setEmptyMessage(String message) {
        emptyLabel.setText(message);
        emptyLabel.setToolTipText(message);
    }

    private int getColumnsForWidth() {
        int width = getWidth();
        return width <= 0 ? itemsPerRow
                : Math.max(1, Math.min(itemsPerRow, (width + GAP) / (ItemComponent.CELL_SIZE + GAP)));
    }

    private void refresh() {
        int nextColumns = getColumnsForWidth();
        if (items.isEmpty()) {
            columns = nextColumns;
            grid.setLayout(new BorderLayout());
        } else if (columns != nextColumns || !(grid.getLayout() instanceof GridLayout)) {
            columns = nextColumns;
            grid.setLayout(new GridLayout(0, columns, GAP, GAP));
        }
        int count = expanded ? items.size() : Math.min(items.size(), columns * maxRows);
        List<ItemComponent> next = new ArrayList<>(items.subList(0, count));
        if (!visibleItems.equals(next) || items.isEmpty() && grid.getComponentCount() == 0) {
            grid.removeAll();
            if (next.isEmpty()) {
                grid.add(emptyLabel);
            } else {
                next.forEach(grid::add);
            }
            visibleItems = next;
        }
        boolean overflow = items.size() > columns * maxRows;
        showMore.setVisible(overflow);
        showMore.setText(expanded ? "Show fewer" : "Show all " + items.size() + " items");
        showMore.setToolTipText(expanded ? "Return to the configured preview height." : "Expand this grid. Use the main sidebar scrollbar to view the remaining items.");
        revalidate();
        repaint();
    }

    @Override
    public void doLayout() {
        if (getColumnsForWidth() != columns) {
            refresh();
        }
        super.doLayout();
    }

    @Override
    public Dimension getPreferredSize() {
        int count = expanded ? items.size() : Math.min(items.size(), getColumnsForWidth() * maxRows);
        int cols = getColumnsForWidth();
        int rows = count == 0 ? 0 : (count + cols - 1) / cols;
        int height = rows == 0 ? emptyLabel.getPreferredSize().height
                : rows * ItemComponent.CELL_SIZE + Math.max(0, rows - 1) * GAP;
        if (items.size() > cols * maxRows) {
            height += 6 + showMore.getPreferredSize().height;
        }
        return new Dimension(cols * ItemComponent.CELL_SIZE + Math.max(0, cols - 1) * GAP, height);
    }

    @Override
    public Dimension getMinimumSize() {
        return new Dimension(ItemComponent.CELL_SIZE, getPreferredSize().height);
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }
}

package com.grindstone.ui.components;

import com.grindstone.content.milestone.MilestoneStatus;
