        preview.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        preview.setPreferredSize(new Dimension(350, 60));
        preview.setToolTipText("Confirm the item name, ID and icon before adding the milestone.");
        info.add(status, BorderLayout.NORTH);
        info.add(preview, BorderLayout.CENTER);
        add(info, BorderLayout.SOUTH);
        search.getDocument().addDocumentListener(new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent event) {
                queryChanged();
            }
            @Override
            public void removeUpdate(DocumentEvent event) {
                queryChanged();
            }
            @Override
            public void changedUpdate(DocumentEvent event) {
                queryChanged();
            }
        });
    }

    private void queryChanged() {
        queryVersion++;
        cancelSearch.run();
        model.clear();
        select(null);
        setStatus("Searching...");
        debounce.restart();
    }

    void search() {
        debounce.stop();
        cancelSearch.run();
        int version = queryVersion;
        String text = search.getText().trim();
        if (text.isEmpty()) {
            setStatus("Enter an item name or numeric ID.");
            return;
        }
        cancelSearch = service.search(text, response -> {
            if (version != queryVersion) {
                return;
            }
            int selectedId = selected == null ? -1 : selected.id;
            updating = true;
            try {
                model.clear();
                List<ItemSearchService.Result> visible = new ArrayList<>(response.results.size());
                ItemSearchService.Result previous = null;
                for (ItemSearchService.Result item : response.results) {
                    if (!available.test(item.id)) {
                        continue;
                    }
                    visible.add(item);
                    if (item.id == selectedId) {
                        previous = item;
                    }
                    if (item.image != null) {
                        item.image.onLoaded(results::repaint);
                    }
                }
                model.addAll(visible);
                if (previous != null) {
                    results.setSelectedValue(previous, true);
                }
                if (response.complete && model.size() == 1) {
                    results.setSelectedIndex(0);
                }
            } finally {
                updating = false;
            }
            setStatus(response.complete && model.isEmpty() && !response.results.isEmpty() ? "Matching items are already unlocked." : response.message);
            select(results.getSelectedValue());
        });
    }

    public void setAvailableItems(IntPredicate available) {
        this.available = available;
    }

    private void select(ItemSearchService.Result item) {
        selected = item;
        preview.setIcon(null);
        preview.setText(item == null ? "No item selected" : "<html>" + HtmlUtils.escape(item.name) + "<br>Item ID: " + item.id + "</html>");
        if (item != null && item.image != null) {
            preview.setIcon(new ImageIcon(item.image));
            item.image.onLoaded(() -> SwingUtilities.invokeLater(() -> {
                if (selected == item) {
                    preview.repaint();
                }
            }));
        }
        onSelection.accept(item);
    }

    public int getSelectedItemId() {
        if (selected == null || !available.test(selected.id)) {
            throw new IllegalArgumentException("Search for an available item and select its name and icon first.");
        }
        return selected.id;
    }

    public boolean hasSelection() {
        return selected != null && available.test(selected.id);
    }
    public String getSelectedItemName() {
        if (selected == null) {
            throw new IllegalArgumentException("Select an item first.");
        }
        return selected.name;
    }
    public void loadItem(int id) {
        search.setText(Integer.toString(id));
        search();
    }

    public void stopSearch() {
        queryVersion++;
        debounce.stop();
        cancelSearch.run();
    }

    public void resumeSearch() {
        if (selected != null && !available.test(selected.id)) {
            select(null);
        }
        if (!search.getText().trim().isEmpty() && selected == null) {
            debounce.restart();
        }
    }

    private void setStatus(String message) {
        status.setText("<html><div style='width: 330px'>" + HtmlUtils.escape(message) + "</div></html>");
        status.setToolTipText(message);
    }

    @Override
    public void removeNotify() {
        stopSearch();
        super.removeNotify();
    }
}

package com.grindstone.ui.item;

import com.grindstone.util.ItemVariants;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.PriorityQueue;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import java.util.function.IntFunction;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/18/2026
 */
@Slf4j
@Singleton
public final class ItemSearchService implements ItemLookup {
    private static final int BATCH_SIZE = 128;
    private static final int RESULT_LIMIT = 50;
    private final Client client;
    private final ClientThread clientThread;
    private final IntFunction<AsyncBufferedImage> images;
    private final List<Result> index = new ArrayList<>();
    private int nextItemId;

    @Inject
    public ItemSearchService(Client client, ClientThread clientThread, ItemManager itemManager) {
        this(client, clientThread, itemManager::getImage);
    }

    ItemSearchService(Client client, ClientThread clientThread, IntFunction<AsyncBufferedImage> images) {
        this.client = client;
        this.clientThread = clientThread;
        this.images = images;
    }

    private static void deliver(AtomicBoolean cancelled, Consumer<Response> callback, Response response) {
        SwingUtilities.invokeLater(() -> {
            if (!cancelled.get()) {
                callback.accept(response);
            }
        });
    }

    static boolean isIdQuery(String query) {
        return query.matches("#?\\d+");
    }

    static int parseId(String query) {
        try {
            return Integer.parseInt(query.startsWith("#") ? query.substring(1) : query);
        } catch (NumberFormatException exception) {
            return -1;
        }
    }

    static boolean matchesName(String name, String query) {
        return matchesName(name, query.trim().toLowerCase(Locale.ROOT).split("\\s+"));
    }

    private static boolean matchesName(String name, String[] words) {
        return matchesNormalized(name.toLowerCase(Locale.ROOT), words);
    }

    private static boolean matchesNormalized(String normalized, String[] words) {
        for (String word : words) {
            if (!normalized.contains(word)) {
                return false;
            }
        }
        return true;
    }

    static int rank(String name, String query) {
        return rankNormalized(name.toLowerCase(Locale.ROOT), query);
    }

    private static int rankNormalized(String name, String query) {
        return name.equals(query) ? 0 : name.startsWith(query) ? 1 : 2;
    }

    @Override
    public Runnable search(String text, Consumer<Response> callback) {
        AtomicBoolean cancelled = new AtomicBoolean();
        String query = text == null ? "" : text.trim().toLowerCase(Locale.ROOT);
        SearchResults matches = new SearchResults(query);
        String[] words = query.split("\\s+");
        boolean idQuery = isIdQuery(query);
        int[] scanned = {0};
        int[] batches = {0};
        clientThread.invokeLater(() -> {
            if (cancelled.get()) {
                return true;
            }
            if (client.getGameState() != GameState.LOGGED_IN) {
                deliver(cancelled, callback, new Response(new ArrayList<>(), "Log in to search client items.", true));
                return true;
            }
            if (idQuery) {
                int id = parseId(query);
                if (id <= 0 || id >= client.getItemCount()) {
                    deliver(cancelled, callback, new Response(new ArrayList<>(), "No item exists for that ID.", true));
                    return true;
                }
                Result result = readItem(id, true);
                List<Result> found = new ArrayList<>();
                if (result != null) {
                    found.add(withImage(result));
                }
                deliver(cancelled, callback, new Response(found, result == null ? "That ID has no usable item definition." : result.id != id ? "Variant resolved to its normal item. Noted and normal quantities are tracked together." : "Item ID resolved. Confirm its name and icon below.", true));
                return true;
            }
            if (query.length() < 2) {
                deliver(cancelled, callback, new Response(new ArrayList<>(), "Enter at least 2 letters, or an item ID.", true));
                return true;
            }
            int end = Math.min(client.getItemCount(), nextItemId + BATCH_SIZE);
            int start = nextItemId;
            long deadline = System.nanoTime() + 3_000_000L;
            while (nextItemId < end && (nextItemId == start || System.nanoTime() < deadline)) {
                Result result = readItem(nextItemId++, false);
                if (result != null) {
                    index.add(result);
                }
            }
            int scanStart = scanned[0];
            while (scanned[0] < index.size() && (scanned[0] == scanStart || System.nanoTime() < deadline)) {
                Result result = index.get(scanned[0]++);
                if (matchesNormalized(result.normalizedName, words)) {
                    matches.add(result);
                }
            }
            boolean complete = nextItemId >= client.getItemCount() && scanned[0] >= index.size();
            if (complete || batches[0]++ % 8 == 0) {
                List<Result> ordered = matches.getResults();
                List<Result> visible = new ArrayList<>();
                for (int i = 0; i < Math.min(RESULT_LIMIT, ordered.size()); i++) {
                    visible.add(withImage(ordered.get(i)));
                }
                String message = !complete ? "Searching client items... "
                        + (client.getItemCount() == 0 ? 0 : nextItemId * 100 / client.getItemCount()) + "%"
                        : matches.getMatchCount() == 0 ? "No matches. Try a shorter name or a numeric ID."
                        : matches.getMatchCount() > RESULT_LIMIT ? "First 50 matches. Refine the name to narrow the list."
                        : matches.getMatchCount() + " matching items. Select one to confirm.";
                deliver(cancelled, callback, new Response(visible, message, complete));
            }
            return complete;
        });
        return () -> cancelled.set(true);
    }

    private Result readItem(int id, boolean explicitId) {
        if (id <= 0) {
            return null;
        }
        try {
            ItemComposition item = client.getItemDefinition(id);
            if (item == null) {
                return null;
            }
            if (item.getNote() != -1 || item.getPlaceholderTemplateId() != -1) {
                if (!explicitId) {
                    return null;
                }
                int normal = ItemVariants.getNormalId(item);
                return normal > 0 && normal < client.getItemCount() && normal != id ? readItem(normal, false) : null;
            }
            String name = item.getMembersName();
            if (name == null || name.trim().isEmpty()) {
                name = item.getName();
            }
            if (name == null || name.trim().isEmpty() || "null".equalsIgnoreCase(name)) {
                return null;
            }
            return new Result(id, name, null);
        } catch (RuntimeException exception) {
            log.debug("Unable to read item definition {}", id, exception);
            return null;
        }
    }

    private Result withImage(Result result) {
        return new Result(result.id, result.name, images.apply(result.id), result.normalizedName);
    }

    /**
     * @author Ayman Yassen
     * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
     * @since 10/18/2026
     */
    public static final class Result {
        public final int id;
        public final String name;
        public final AsyncBufferedImage image;
        private final String normalizedName;

        public Result(int id, String name, AsyncBufferedImage image) {
            this(id, name, image, name.toLowerCase(Locale.ROOT));
        }

        private Result(int id, String name, AsyncBufferedImage image, String normalizedName) {
            this.id = id;
            this.name = name;
            this.image = image;
            this.normalizedName = normalizedName;
        }
    }

    /**
     * @author Ayman Yassen
     * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
     * @since 11/04/2026
     */
    static final class SearchResults {
        private final Comparator<Result> order;
        private final PriorityQueue<Result> best;
        @Getter(AccessLevel.PACKAGE)
        private int matchCount;

        SearchResults(String query) {
            order = Comparator.comparingInt((Result result) -> rankNormalized(result.normalizedName, query)).thenComparing(result -> result.name, String.CASE_INSENSITIVE_ORDER).thenComparingInt(result -> result.id);
            best = new PriorityQueue<>(RESULT_LIMIT, order.reversed());
        }

        void add(Result result) {
            matchCount++;
            if (best.size() < RESULT_LIMIT) {
                best.add(result);
            } else if (order.compare(result, best.peek()) < 0) {
                best.poll();
                best.add(result);
            }
        }

        List<Result> getResults() {
            List<Result> results = new ArrayList<>(best);
            results.sort(order);
            return results;
        }
    }

    /**
     * @author Ayman Yassen
     * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
     * @since 10/18/2026
     */
    public static final class Response {
        public final List<Result> results;
        public final String message;
        public final boolean complete;

        public Response(List<Result> results, String message, boolean complete) {
            this.results = Collections.unmodifiableList(new ArrayList<>(results));
            this.message = message;
            this.complete = complete;
        }
    }
}

package com.grindstone.ui.util;

import java.awt.Component;
import java.awt.GraphicsConfiguration;
import java.awt.GraphicsEnvironment;
import java.awt.Insets;
import java.awt.Rectangle;
import java.awt.Toolkit;
import java.awt.Window;
import javax.swing.SwingUtilities;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/20/2026
 */
public final class DialogPlacement {
    private DialogPlacement() {
    }

    public static Component getOwner(Component component) {
        if (component == null) {
            return null;
        }
        if (component instanceof Window) {
            return component;
        }
        Window window = SwingUtilities.getWindowAncestor(component);
        return window == null ? component : window;
    }

    public static Rectangle getUsableBounds(Component component) {
        Component owner = getOwner(component);
        GraphicsConfiguration configuration = owner == null ? null : owner.getGraphicsConfiguration();
        if (configuration == null) {
            configuration = GraphicsEnvironment.getLocalGraphicsEnvironment().getDefaultScreenDevice().getDefaultConfiguration();
        }
        Rectangle bounds = new Rectangle(configuration.getBounds());
        Insets insets = Toolkit.getDefaultToolkit().getScreenInsets(configuration);
        bounds.x += insets.left;
        bounds.y += insets.top;
        bounds.width -= insets.left + insets.right;
        bounds.height -= insets.top + insets.bottom;
        return bounds;
    }

    public static void center(Window dialog, Component component) {
        Rectangle bounds = getUsableBounds(component);
        dialog.setSize(Math.min(dialog.getWidth(), Math.max(1, bounds.width - 40)), Math.min(dialog.getHeight(), Math.max(1, bounds.height - 40)));
        dialog.setLocationRelativeTo(getOwner(component));
        dialog.setLocation(Math.max(bounds.x, Math.min(dialog.getX(), bounds.x + bounds.width - dialog.getWidth())), Math.max(bounds.y, Math.min(dialog.getY(), bounds.y + bounds.height - dialog.getHeight())));
    }
}

package com.grindstone.ui.util;

import com.grindstone.content.milestone.Milestone;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
public final class MilestoneCardCache<T> {
    private final Map<Milestone, List<?>> keys = new IdentityHashMap<>();
    private final Map<Milestone, T> cards = new IdentityHashMap<>();
    public synchronized T get(Milestone goal, List<?> key) {
        return key.equals(keys.get(goal)) ? cards.get(goal) : null;
    }
    public synchronized void put(Milestone goal, List<?> key, T card) {
        keys.put(goal, key);
        cards.put(goal, card);
    }
    public synchronized void invalidate(Milestone goal) {
        keys.remove(goal);
        cards.remove(goal);
    }
    public synchronized void clear() {
        keys.clear();
        cards.clear();
    }
    public synchronized void retain(List<Milestone> goals) {
        Set<Milestone> retained = Collections.newSetFromMap(new IdentityHashMap<>());
        retained.addAll(goals);
        keys.keySet().retainAll(retained);
        cards.keySet().retainAll(retained);
    }
}

package com.grindstone.ui.util;

import com.grindstone.content.milestone.Milestone;
import com.grindstone.content.milestone.impl.experience.SessionExperienceMilestone;
import com.grindstone.content.milestone.impl.experience.SkillExperienceMilestone;
import com.grindstone.content.milestone.impl.level.SkillLevelMilestone;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import net.runelite.api.Skill;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
public final class SkillMilestoneGrouping {
    private SkillMilestoneGrouping() {
    }

    public static Skill getSkill(Milestone goal) {
        if (goal instanceof SessionExperienceMilestone) {
            SessionExperienceMilestone session = (SessionExperienceMilestone) goal;
            return session.isTotal() ? null : session.getSkill();
        }
        return goal instanceof SkillLevelMilestone ? ((SkillLevelMilestone) goal).getSkill() : goal instanceof SkillExperienceMilestone ? ((SkillExperienceMilestone) goal).getSkill() : null;
    }

    public static <T> List<List<T>> group(List<T> rows, Function<T, Milestone> goal) {
        Map<Object, List<T>> groups = new LinkedHashMap<>();
        for (T row : rows) {
            Skill skill = getSkill(goal.apply(row));
            groups.computeIfAbsent(skill == null ? new Object() : skill, key -> new ArrayList<>()).add(row);
        }
        return new ArrayList<>(groups.values());
    }
}

